class MissionManager{
  constructor(startCash){this.startCash=startCash;this.index=0;this.viewed=[];this.drawn=[];this.missions=[
    ['Làm quen Watchlist','Xem ít nhất 3 mã khác nhau.','symbols',3],['Giao dịch đầu tiên','Mở một vị thế LONG hoặc SHORT.','trade',1],['Đổi khung thời gian','Thử một timeframe khác 1D.','timeframe',1],['Vẽ vùng giá','Dùng Rectangle đánh dấu một vùng.','rect',1],['Dùng Fibonacci','Vẽ Fibonacci thoái lui.','fib',1],['Lệnh chờ','Đặt một lệnh LIMIT.','limit',1],['Lệnh phá vỡ','Đặt một lệnh STOP.','stop',1],['Quản trị vị thế','Đặt Stop Loss hoặc Take Profit.','risk',1],['Chốt giao dịch','Đóng ít nhất một vị thế.','close',1],['Mục tiêu lợi nhuận','Đạt Net P/L +1.000.000đ.','pnl',1_000_000],['Đa dạng hóa','Nắm ít nhất 3 mã cùng lúc.','positions',3],['Tăng tài khoản','Đưa Equity lên +5% vốn đầu.','equity',startCash*1.05]
  ].map(([title,desc,kind,target])=>({title,desc,kind,target,done:false}))}
  markView(s){if(!this.viewed.includes(s))this.viewed.push(s)}markDraw(k){if(!this.drawn.includes(k))this.drawn.push(k)}
  value(market,player,ui,m){switch(m.kind){case'symbols':return this.viewed.length;case'trade':return player.firstTradeDone?1:0;case'timeframe':return ui.timeframe!=='1D'?1:0;case'rect':return this.drawn.includes('RECT')?1:0;case'fib':return this.drawn.includes('FIB')?1:0;case'limit':return player.limitOrderDone?1:0;case'stop':return player.stopOrderDone?1:0;case'risk':return Object.values(player.positions).some(p=>p.stopLoss>0||p.takeProfit>0)?1:0;case'close':return player.closeDone?1:0;case'pnl':return player.netPnl(market);case'positions':return Object.keys(player.positions).length;case'equity':return player.equity(market);default:return 0}}
  update(market,player,ui){while(this.index<this.missions.length){const m=this.missions[this.index],v=this.value(market,player,ui,m);if(v<m.target)break;m.done=true;this.index++}}
  current(){return this.missions[this.index]||null}
  toJSON(){return{startCash:this.startCash,index:this.index,viewed:this.viewed,drawn:this.drawn,missions:this.missions}}
  static fromJSON(o){const m=Object.create(MissionManager.prototype);Object.assign(m,{startCash:o.startCash,index:o.index||0,viewed:o.viewed||[],drawn:o.drawn||[],missions:o.missions||[]});return m}
}

class SaveDB{
  constructor(){this.db=null}
  async open(){if(!('indexedDB'in window))return null;this.db=await new Promise((resolve,reject)=>{const r=indexedDB.open(DB_NAME,1);r.onupgradeneeded=()=>{const db=r.result;if(!db.objectStoreNames.contains(DB_STORE))db.createObjectStore(DB_STORE)};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});return this.db}
  async get(){if(!this.db)return null;return await new Promise((resolve,reject)=>{const tx=this.db.transaction(DB_STORE,'readonly'),r=tx.objectStore(DB_STORE).get(DB_KEY);r.onsuccess=()=>resolve(r.result||null);r.onerror=()=>reject(r.error)})}
  async put(data){if(!this.db)return false;await new Promise((resolve,reject)=>{const tx=this.db.transaction(DB_STORE,'readwrite');tx.objectStore(DB_STORE).put(data,DB_KEY);tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error)});return true}
  async clear(){if(!this.db)return;await new Promise((resolve,reject)=>{const tx=this.db.transaction(DB_STORE,'readwrite');tx.objectStore(DB_STORE).delete(DB_KEY);tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error)})}
}

