function toast(msg,type='info'){const el=document.createElement('div');el.className=`toast ${type}`;el.textContent=msg;dom.toast.appendChild(el);setTimeout(()=>{el.style.opacity='0';el.style.transform='translateY(-4px)'},3000);setTimeout(()=>el.remove(),3400)}
function showLoading(show,title='',text='',progress=null){dom.loading.hidden=!show;if(title)dom.loadingTitle.textContent=title;if(text)dom.loadingText.textContent=text;if(progress!=null)dom.loadingProgress.style.width=`${clamp(progress,0,1)*100}%`}
function snapshot(){return{saveVersion:SAVE_VERSION,version:VERSION,savedAt:Date.now(),difficulty:appState.difficulty,seed:appState.seed,market:appState.market.toJSON(),player:appState.player.toJSON(),missions:appState.missions.toJSON(),ui:{selected:appState.selected,exchange:appState.exchange,timeframe:appState.timeframe,chartMode:appState.chartMode,speed:appState.speed,paused:appState.paused,leverage:appState.leverage,visibleCount:appState.visibleCount,scrollOffset:appState.scrollOffset,priceScale:appState.priceScale,drawings:appState.drawings}}}
