function restore(data){if(!data||data.saveVersion!==SAVE_VERSION)return false;appState.difficulty=data.difficulty||'MEDIUM';appState.seed=data.seed||1;appState.market=Market.fromJSON(data.market);appState.player=Player.fromJSON(data.player);appState.missions=MissionManager.fromJSON(data.missions);Object.assign(appState,{selected:data.ui?.selected||'FPT',exchange:data.ui?.exchange||SYMBOL_EXCHANGE[data.ui?.selected]||'HOSE',timeframe:data.ui?.timeframe||'1D',chartMode:data.ui?.chartMode||'CANDLE',speed:data.ui?.speed||1,paused:!!data.ui?.paused,leverage:data.ui?.leverage||1,visibleCount:data.ui?.visibleCount||120,scrollOffset:data.ui?.scrollOffset||0,priceScale:data.ui?.priceScale||1,drawings:data.ui?.drawings||[],redo:[]});return true}

async function startNewGame(difficulty='MEDIUM',seed=randomSeed()){
  showLoading(true,'Đang tạo thị trường mới','Đang tạo lịch sử 2 năm…',0);appState.difficulty=difficulty;appState.seed=Number(seed)||randomSeed();appState.market=new Market(appState.seed);appState.player=new Player(DIFFICULTIES[difficulty].cash);appState.missions=new MissionManager(appState.player.startCash);Object.assign(appState,{selected:'FPT',exchange:'HOSE',timeframe:'1D',chartMode:'CANDLE',speed:1,paused:false,side:'BUY',orderType:'MARKET',leverage:1,bottomTab:'NEWS',sideTab:'TRADE',tool:'CURSOR',visibleCount:120,scrollOffset:0,priceScale:1,drawings:[],redo:[],draft:null,lineDrag:null});
  await appState.market.generateHistory(PREGEN_DAYS,(p,t)=>showLoading(true,'Đang tạo thị trường mới',t,p));appState.missions.markView('FPT');await saveGame(true);showLoading(false);dom.newGame.hidden=true;syncControls();renderAll(true);toast(`Thị trường mới · Seed ${appState.seed}`,'success')
}

