function chartMetrics(){const c=dom.canvas,rect=c.getBoundingClientRect(),dpr=Math.max(1,window.devicePixelRatio||1);if(c.width!==Math.round(rect.width*dpr)||c.height!==Math.round(rect.height*dpr)){c.width=Math.round(rect.width*dpr);c.height=Math.round(rect.height*dpr)}const w=rect.width,h=rect.height,left=8,right=72,top=10,bottom=27,volumeH=Math.max(48,h*0.18),plot={x:left,y:top,w:Math.max(10,w-left-right),h:Math.max(50,h-top-bottom-volumeH-5)},vol={x:left,y:top+plot.h+5,w:Math.max(10,w-left-right),h:volumeH},yAxis={x:w-right,y:top,w:right,h:h-top-bottom},xAxis={x:left,y:h-bottom,w:w-left-right,h:bottom};return{c,ctx:c.getContext('2d'),rect,dpr,w,h,plot,vol,yAxis,xAxis}}
