function liveLines(){const out=[];for(const o of appState.player.orders){if(o.symbol!==appState.selected)continue;if(o.intent==='OPEN'&&['OPEN','PARTIAL'].includes(o.status)&&['LIMIT','STOP'].includes(o.orderType)&&o.limitPrice>0)out.push({kind:'ORDER',id:o.oid,price:o.limitPrice,color:lineColor(o),label:`#${o.oid} ${o.side} ${o.orderType}`,draggable:true});if(o.intent==='OPEN'&&o.filledQty>0&&o.avgFill>0)out.push({kind:'ENTRY',id:o.oid,price:o.avgFill,color:o.positionSide==='LONG'?COLORS.green:COLORS.red,label:`${o.positionSide==='LONG'?'BUY':'SHORT'} #${o.oid}`,draggable:false})}const p=appState.player.positions[appState.selected];if(p){out.push({kind:'AVG',id:0,price:p.avgCost,color:p.side==='LONG'?COLORS.green:COLORS.red,label:`GIÁ VỐN ${p.side}`,draggable:false});if(p.stopLoss>0)out.push({kind:'STOP_LOSS',id:0,price:p.stopLoss,color:COLORS.red,label:'STOP LOSS',draggable:true});if(p.takeProfit>0)out.push({kind:'TAKE_PROFIT',id:0,price:p.takeProfit,color:COLORS.green,label:'TAKE PROFIT',draggable:true})}return out}
function nearestLine(mouseY,bars,m,conv,maxPx=7){let best=null;for(const l of liveLines()){if(!l.draggable)continue;const yy=conv.y(l.price),dist=Math.abs(mouseY-yy);if(dist<=maxPx&&(!best||dist<best.dist))best={...l,y:yy,dist}}return best}
