  if(!appState.market)return;const m=chartMetrics(),ctx=m.ctx;ctx.setTransform(m.dpr,0,0,m.dpr,0,0);ctx.clearRect(0,0,m.w,m.h);ctx.fillStyle=COLORS.bg;ctx.fillRect(0,0,m.w,m.h);const {bars}=chartData();if(!bars.length)return;const conv=xyConverters(bars,m),{x,y,step,range}=conv;
